import{_ as a,o as t,c as i,ak as r}from"./chunks/framework.Cq0X4QeM.js";const p=JSON.parse(`{"title":"OSCP · Active Directory : fondamentaux","description":"Comprendre les objets AD et les mécanismes d'authentification.","frontmatter":{"title":"OSCP · Active Directory : fondamentaux","description":"Comprendre les objets AD et les mécanismes d'authentification."},"headers":[],"relativePath":"oscp/ad-theorie.md","filePath":"oscp/ad-theorie.md"}`),o={name:"oscp/ad-theorie.md"};function n(s,e,l,c,d,u){return t(),i("div",null,e[0]||(e[0]=[r('<h1 id="active-directory-fondamentaux" tabindex="-1">Active Directory : fondamentaux <a class="header-anchor" href="#active-directory-fondamentaux" aria-label="Permalink to &quot;Active Directory : fondamentaux&quot;">​</a></h1><p>Les concepts essentiels avant de commencer l&#39;énumération du domaine.</p><h2 id="domaine-et-controleur-de-domaine" tabindex="-1">Domaine et contrôleur de domaine <a class="header-anchor" href="#domaine-et-controleur-de-domaine" aria-label="Permalink to &quot;Domaine et contrôleur de domaine&quot;">​</a></h2><p>Le domaine rassemble comptes, ordinateurs, groupes et droits. Le contrôleur de domaine (DC) fournit notamment les services LDAP et Kerberos.</p><p>Exemple de domaine : domain.com.</p><h2 id="authentification" tabindex="-1">Authentification <a class="header-anchor" href="#authentification" aria-label="Permalink to &quot;Authentification&quot;">​</a></h2><ul><li>Kerberos : le client demande un ticket initial (TGT), puis des tickets de service (TGS).</li><li>NTLM : protocole d&#39;authentification par défi-réponse.</li><li>SPN : nom associant un service à un compte Active Directory.</li></ul><h2 id="valeurs-a-connaitre" tabindex="-1">Valeurs à connaître <a class="header-anchor" href="#valeurs-a-connaitre" aria-label="Permalink to &quot;Valeurs à connaître&quot;">​</a></h2><ul><li>DONT_REQ_PREAUTH : indicateur d&#39;un compte pouvant ne pas exiger la préauthentification Kerberos.</li><li>DS-Replication-Get-Changes : droit utilisé dans les mécanismes de réplication de l&#39;annuaire.</li></ul><p>Ces éléments sont des noms d&#39;attributs et de droits, pas des commandes.</p><h2 id="passer-a-la-pratique" tabindex="-1">Passer à la pratique <a class="header-anchor" href="#passer-a-la-pratique" aria-label="Permalink to &quot;Passer à la pratique&quot;">​</a></h2><ul><li><a href="./ad-enumeration">Énumération Active Directory</a></li><li><a href="./ad-techniques">Techniques Active Directory</a></li><li><a href="./ad-lateral">Mouvement latéral</a></li></ul><p>Source : <a href="https://www.emmanuelsolis.com/oscp.html" target="_blank" rel="noreferrer">Notes OSCP Emmanuel Solis</a>.</p>',13)]))}const h=a(o,[["render",n]]);export{p as __pageData,h as default};
